function shuffledDeck(){const a=QUESTIONS.map((_,i)=>i);for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function nextQuestion(r){r.answerDeadline=0;r.flightDuration=0;r.blockedPlayers=new Set();if(!r.deck.length)r.deck=shuffledDeck();const raw=QUESTIONS[r.deck.pop()];const pairs=raw[1].map((text,index)=>({text,index}));for(let i=pairs.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pairs[i],pairs[j]]=[pairs[j],pairs[i]]}r.question={text:raw[0],answers:pairs.map(x=>x.text),correct:pairs.findIndex(x=>x.index===raw[2])};r.answerer=null;r.flight=null;return r.question}
function publicState(r){const players={};for(const [id,p] of r.players)players[id]={id,name:p.name,points:p.points,platform:p.platform,stars:p.stars,slot:Number.isInteger(p.slot)?p.slot:0,online:p.online!==false};return {room:r.code,roomName:r.name||'Open room',players,hostId:r.hostId,question:r.question?{text:r.question.text,answers:r.question.answers}:null,answerer:r.answerer,blockedPlayers:[...(r.blockedPlayers||new Set())],answerDeadline:r.answerDeadline,flight:r.flight,flightDuration:r.flightDuration,started:r.started}}
function broadcast(r,type='state',extra={}){const payload=JSON.stringify({type,...extra,state:publicState(r)});for(const c of r.clients)if(c.readyState===1)c.send(payload)}
function roomCode(){let c;do{c=Math.random().toString(36).slice(2,8).toUpperCase()}while(rooms.has(c));return c}
function nextSlot(r){const used=new Set([...r.players.values()].map(p=>p.slot));for(let i=0;i<4;i++)if(!used.has(i))return i;return 0}
function startIfNeeded(r){if(!r.started&&r.players.size>=1){r.started=true;for(const p of r.players.values())ensureDaily(accounts[p.username]);nextQuestion(r);broadcast(r,'event',{text:'🚀 Game started! First to 10 points wins.'})}}
function sendDaily(ws,username){const a=accounts[username];if(a&&ws.readyState===1)ws.send(JSON.stringify({type:'daily',daily:questView(a),stars:a.stars||0}))}
function addGame(username,r){const a=accounts[username];if(!a)return;const d=ensureDaily(a);if(!d.played){d.played=true;completeQuest(a,'dailyPlay')}if(r.players.size>1){for(const p of r.players.values()){const other=accounts[p.username];if(other){const od=ensureDaily(other);od.friendly=true;completeQuest(other,'friendly')}}}a.games=(a.games||0)+1;saveAccounts()}
function recordCorrect(a){const d=ensureDaily(a);d.correctStreak++;d.correctToday++;if(d.correctStreak>=3)completeQuest(a,'correctStreak');if(d.correctToday>=5)completeQuest(a,'correctToday');saveAccounts()}
function finishGame(p){const a=accounts[p.username];if(!a)return;const d=ensureDaily(a);d.wins=(Number(d.wins)||0)+1;d.winStreak=(Number(d.winStreak)||0)+1;d.correctStreak=0;if(d.wins>=1)completeQuest(a,'dailyWin');if(d.winStreak>=3)completeQuest(a,'winStreak');a.wins=(Number(a.wins)||0)+1;a.stars=(Number(a.stars)||0)+1;p.stars=a.stars;try{saveAccounts()}catch(err){console.error('[rank] failed to save winner stars:',err&&err.stack||err)}}
function loseGameStreak(username){const a=accounts[username];if(!a)return;ensureDaily(a).winStreak=0;saveAccounts()}
