 if(req.method==='POST'&&p==='/api/login'){const b=await readBody(req),user=String(b.username||'').trim().toLowerCase(),pass=String(b.password||''),a=accounts[user];if(!a||hashPassword(pass,a.salt)!==a.hash)return sendJson(res,401,{error:'Incorrect username or password.'});if(activeSockets.has(user))return sendJson(res,409,{error:'This account is already active in another tab or device. Log out there first.'});if(a.token){a.token=null;saveAccounts()}const token=issueToken(user);return sendJson(res,200,{token,username:user,stars:a.stars||0,wins:a.wins||0,games:a.games||0,daily:questView(a)})}
 if(req.method==='POST'&&p==='/api/logout'){const b=await readBody(req),x=accountFromToken(b.token);if(x){const user=x[0],sock=activeSockets.get(user);x[1].token=null;saveAccounts();if(sock){activeSockets.delete(user);try{sock.close(1000,'Logged out')}catch{}}}return sendJson(res,200,{ok:true})}
 if(req.method==='GET'&&p==='/api/me'){const x=accountFromToken(u.searchParams.get('token'));if(!x)return sendJson(res,401,{error:'Not logged in'});const [user,a]=x;return sendJson(res,200,{username:user,stars:a.stars||0,wins:a.wins||0,games:a.games||0,daily:questView(a)})}
 if(req.method==='GET'&&p==='/api/rooms'){const list=[...rooms.values()].filter(r=>r.players.size>0).map(r=>({code:r.code,name:r.name||'Open room',players:r.players.size,maxPlayers:4,started:!!r.started})).sort((a,b)=>a.players-b.players);return sendJson(res,200,{rooms:list})}
