  if(m.type==='thrust'&&r.answerer===id&&r.flight===id){const p=r.players.get(id);if(!p)return;if(m.on){if(!p.thrustAt)p.thrustAt=Date.now();broadcast(r,'flight',{playerId:id,active:true,duration:r.flightDuration||1600});return}const held=p.thrustAt?Date.now()-p.thrustAt:0;p.thrustAt=0;const target=r.flightDuration||1600;const tolerance=380;const success=Math.abs(held-target)<=tolerance;r.flight=null;r.answerer=null;r.answerDeadline=0;if(success){p.platform=Math.min(PLATFORM_X.length-1,p.platform+1);p.points++;const aa=accounts[p.username];if(aa){try{const d=ensureDaily(aa);d.pointsThisGame=Math.max(Number(d.pointsThisGame)||0,p.points);if(d.pointsThisGame>=5)completeQuest(aa,'pointsGame');p.stars=Number(aa.stars)||0;saveAccounts();sendDaily(ws,p.username)}catch(err){console.error('[landing] account save failed after point:',err&&err.stack||err)}}if(p.points>=10){finishGame(p);if(aa)sendDaily(ws,p.username);for(const other of r.players.values()){if(other.id!==p.id)loseGameStreak(other.username)}broadcast(r,'event',{text:`🏆 ${p.name} WON! 10 points! +1 ⭐ Account stars saved.`});setTimeout(()=>{if(!rooms.has(r.code))return;for(const q of r.players.values()){q.points=0;q.platform=0;const qa=accounts[q.username];if(qa){ensureDaily(qa).pointsThisGame=0;saveAccounts()}}nextQuestion(r);broadcast(r,'event',{text:'🔄 New round! First to 10 points wins.'})},1800)}else{nextQuestion(r);broadcast(r,'event',{text:`🚀 ${p.name} landed on asteroid ${p.platform+1}! +1 point.`})}}else{nextQuestion(r);broadcast(r,'event',{text:held<target?'⬇️ Too early — you released before reaching the asteroid. Back to your last asteroid.':'⬇️ Too late — you released after passing the landing window. Back to your last asteroid.'})}broadcast(r,'state');return}
